        const previousForFirst = firstId ? previousEpisodeForModel(priorEpisodes, firstId) : null;
        const priorFirstWins = firstId ? priorEpisodes.filter(item => item.calloutOrder?.[0] === firstId).length : 0;
        if (firstId && previousForFirst?.bottomTwoIds?.includes(firstId)) {
            candidates.push({ type: "turnaround", bank: "turnaround", priority: 84, lead: "A model who was recently in serious danger suddenly finds new momentum and begins changing the way the competition sees them." });
        }
        else if (firstId && priorFirstWins === 0 && episode.index > 1) {
            candidates.push({ type: "breakout", bank: "breakout", priority: 76, lead: "An unexpected contestant begins to emerge from the middle of the pack and looks much more dangerous than before." });
        }
        if (firstId && episode.challengeWinnerId === firstId) {
            candidates.push({ type: "dominant", bank: "dominant", priority: 78, lead: "One model seems to put the entire week together, carrying confidence from the challenge straight into the photoshoot." });
        }
