        const previousFirst = previousEpisode?.calloutOrder?.[0] || null;
        if (previousFirst && episode.bottomTwoIds?.includes(previousFirst)) {
            candidates.push({ type: "fall", bank: "fall", priority: 82, lead: "A contestant who looked nearly untouchable only a week ago suddenly discovers how quickly momentum can disappear." });
        }
