        $("#challengeImmunity").checked = false;
        $("#comeback").checked = false;
        $("#disableRiggory").checked = false;
        $("#allowNonEliminations").checked = false;
        $("#allowDoubleEliminations").checked = false;
        $("#allowQuits").checked = false;
