    function clearSeasonSimulation() {
        clearTimeout(state.calloutTimer);
        clearTimeout(state.castingTimer);
        clearTimeout(state.makeoverTimer);
        stopFanFavoriteAnimation();
        stopVotingComebackAnimation();
        stopFanVotingAnimations();
        state.calloutTimer = null;
        state.castingTimer = null;
        state.makeoverTimer = null;
        state.fanFavoriteTimer = null;
        state.seasonEpisodes = [];
        state.finalistIds = [];
        state.finalRankingIds = [];
        state.winnerId = null;
        state.currentEpisodeIndex = 0;
        state.runtimeProfiles = new Map();
        state.relationships = new Map();
        state.houseEventHistory = [];
        state.castingEpisode = null;
        state.competitionCastIds = [];
        state.viewingCasting = false;
        state.viewingFinale = false;
        state.finaleEpisode = null;
        if ($("#roundSelect"))
            $("#roundSelect").replaceChildren();
    }
    function randomBetween(min, max) {
        return min + Math.random() * (max - min);
    }
    function weightedRandom(items, weightFn) {
        if (!items.length)
            return null;
        const weights = items.map(item => Math.max(0.01, Number(weightFn(item)) || 0.01));
        const total = weights.reduce((sum, value) => sum + value, 0);
        let cursor = Math.random() * total;
        for (let i = 0; i < items.length; i += 1) {
            cursor -= weights[i];
            if (cursor <= 0)
                return items[i];
        }
        return items.at(-1);
    }
    function normalizeHiddenTraits(traits = {}) {
        return Object.fromEntries(HIDDEN_TRAIT_KEYS.map(key => [
            key,
            clamp(Number(traits?.[key] ?? DEFAULT_TRAIT), TRAIT_MIN, TRAIT_MAX)
        ]));
    }
    function randomizedHiddenTraits() {
        return Object.fromEntries(HIDDEN_TRAIT_KEYS.map(key => [
            key,
            TRAIT_MIN + Math.floor(Math.random() * TRAIT_MAX)
        ]));
    }
    function buildRuntimeProfile(model) {
        const traits = normalizeHiddenTraits(model.hiddenTraits || DEFAULT_HIDDEN_TRAITS);
        return {
            id: model.id,
            model,
            skills: { ...normalizeSkills(model.skills) },
            traits,
            state: {
                fatigue: randomBetween(2, 10),
                stress: randomBetween(8, 22),
                confidence: randomBetween(-2, 3)
            },
            perception: {
                judges: clamp(50 + (traits.potential - DEFAULT_TRAIT) * 1.2 + (traits.professionalism - DEFAULT_TRAIT) * .45 + randomBetween(-3, 3), 20, 80),
                fans: clamp(50 + (traits.charisma - DEFAULT_TRAIT) * 1.25 + randomBetween(-4, 4), 20, 80)
            },
            history: {
                challenges: [],
                shoots: [],
                totals: [],
                bottoms: 0,
                challengeWins: 0,
                bestPhotos: 0,
                episodeVisibility: 0,
                breakdowns: 0,
                conflictIncidents: 0
            }
        };
    }
    function profileById(id) {
        return state.runtimeProfiles.get(id);
    }
    function relationshipKey(a, b) {
        return [String(a), String(b)].sort().join("::");
    }
    function getRelationship(a, b) {
        if (a === b)
            return 100;
        return state.relationships.get(relationshipKey(a, b)) ?? 0;
    }
    function changeRelationship(a, b, amount) {
        if (!a || !b || a === b)
            return;
        const key = relationshipKey(a, b);
        state.relationships.set(key, clamp(getRelationship(a, b) + amount, -100, 100));
    }
    function initializeRuntime(cast) {
        state.runtimeProfiles = new Map(cast.map(model => [model.id, buildRuntimeProfile(model)]));
        state.relationships = new Map();
        for (let i = 0; i < cast.length; i += 1) {
            for (let j = i + 1; j < cast.length; j += 1) {
                const a = profileById(cast[i].id);
                const b = profileById(cast[j].id);
                const social = ((a.traits.sociability + b.traits.sociability) / 2 - DEFAULT_TRAIT) * 1.05;
                state.relationships.set(relationshipKey(a.id, b.id), clamp(randomBetween(-8, 10) + social, -20, 24));
            }
        }
    }
    function average(values) {
        return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : 0;
    }
    function recentTrajectory(profile) {
        const scores = profile.history.totals;
        if (scores.length < 3)
            return 0;
        const recent = average(scores.slice(-2));
        const previous = average(scores.slice(-4, -2).length ? scores.slice(-4, -2) : scores.slice(0, -2));
        return clamp(recent - previous, -2, 2);
    }
    function seasonAverage(profile) {
        return average(profile.history.totals);
    }
    function skillWeightedBase(profile, weights) {
        return Object.entries(weights).reduce((sum, [key, weight]) => {
            const value = key === "random"
                ? randomBetween(SKILL_MIN, SKILL_MAX)
                : (profile.skills[key] || DEFAULT_SKILL);
            return sum + value * weight;
        }, 0);
    }
    function performanceVariance(profile) {
        const amplitude = clamp(1.48 - (profile.traits.consistency - DEFAULT_TRAIT) * .10, .72, 2.15);
        return randomBetween(-amplitude, amplitude);
    }
    function scoreAssignment(profile, assignment, kind) {
        const base = skillWeightedBase(profile, assignment.weights);
        const unfamiliarity = assignment.unfamiliarity ?? 5;
        const difficulty = assignment.difficulty ?? 5;
        const adaptability = ((profile.traits.adaptability - DEFAULT_TRAIT) / 7) * (unfamiliarity / 10) * .58;
        const composure = ((profile.traits.confidence - DEFAULT_TRAIT) / 7) * .22;
        const professional = kind === "challenge" ? ((profile.traits.professionalism - DEFAULT_TRAIT) / 7) * .18 : 0;
        const currentConfidence = (profile.state.confidence / 20) * .24;
        const stressPenalty = (profile.state.stress / 100) * .58;
        const fatiguePenalty = (profile.state.fatigue / 100) * .58;
        const difficultyPenalty = Math.max(0, difficulty - 5) * .055;
        const result = base + adaptability + composure + professional + currentConfidence - stressPenalty - fatiguePenalty - difficultyPenalty + performanceVariance(profile);
        return clamp(Math.round(result * 100) / 100, SKILL_MIN, SKILL_MAX);
    }
    function addFatigue(profile, amount) {
        const multiplier = clamp(1 - (profile.traits.stamina - DEFAULT_TRAIT) * .045, .62, 1.35);
        profile.state.fatigue = clamp(profile.state.fatigue + amount * multiplier, 0, 100);
    }
    function changeStress(profile, amount) {
        profile.state.stress = clamp(profile.state.stress + amount, 0, 100);
    }
    function changeConfidence(profile, amount) {
        profile.state.confidence = clamp(profile.state.confidence + amount, -20, 20);
    }
    function changeJudgeFavor(profile, amount) {
        profile.perception.judges = clamp(profile.perception.judges + amount, 0, 100);
    }
    function changeFanFavor(profile, amount) {
        profile.perception.fans = clamp(profile.perception.fans + amount, 0, 100);
    }
    function overnightRecovery(profiles) {
        profiles.forEach(profile => {
            const fatigueRecovery = 12 + (profile.traits.stamina - DEFAULT_TRAIT) * .9;
            const stressRecovery = 8 + (profile.traits.resilience - DEFAULT_TRAIT) * .55;
            profile.state.fatigue = clamp(profile.state.fatigue - fatigueRecovery, 0, 100);
            profile.state.stress = clamp(profile.state.stress - stressRecovery, 0, 100);
            profile.state.confidence *= .72;
        });
    }
    function growSkill(profile, key, amount) {
        if (!key || !(key in profile.skills))
            return;
        const current = profile.skills[key];
        const progress = (current - SKILL_MIN) / (SKILL_MAX - SKILL_MIN);
        const learningMultiplier = clamp(1.25 - progress * .90, .35, 1.25);
        profile.skills[key] = clamp(current + amount * learningMultiplier, SKILL_MIN, SKILL_MAX);
    }
