    function makeoverPoolForGender(gender) {
        const normalized = String(gender || "").toLowerCase().replace(/[\s_-]+/g, "");
        if (["female", "woman", "girl", "f"].includes(normalized))
            return FEMALE_MAKEOVERS;
        if (["male", "man", "boy", "m"].includes(normalized))
            return MALE_MAKEOVERS;
        return [...FEMALE_MAKEOVERS, ...MALE_MAKEOVERS];
    }
    function createMakeoverAssignments(models) {
        const used = new Set();
        return models.map(model => {
            const pool = makeoverPoolForGender(model.gender);
            const available = pool.filter(makeover => !used.has(makeover));
            const makeover = randomItem(available.length ? available : pool);
            if (makeover)
                used.add(makeover);
            return { modelId: model.id, makeover: makeover || "A polished new editorial look." };
        });
    }
    function generateMakeoverEntries(profiles, makeoverAssignments) {
        const makeoverById = new Map(makeoverAssignments.map(item => [item.modelId, item.makeover]));
        return profiles.map(profile => ({
            model: profile.model,
            challenge: null,
            challengeComment: "",
            makeover: makeoverById.get(profile.id) || null
        }));
    }
