    function assignmentOverlap(a, b) {
        if (!a || !b)
            return 0;
        const skillOverlap = SKILL_KEYS.reduce((sum, key) => sum + (a.weights?.[key] || 0) * (b.weights?.[key] || 0), 0);
        const randomOverlap = (a.weights?.random || 0) * (b.weights?.random || 0);
        return skillOverlap + randomOverlap;
    }
    const SHOOT_CATEGORY_CACHE = new WeakMap();
    function cachedShootCommentCategory(assignment) {
        if (!assignment || typeof assignment !== "object")
            return shootCommentCategory(assignment);
        if (SHOOT_CATEGORY_CACHE.has(assignment))
            return SHOOT_CATEGORY_CACHE.get(assignment);
        const category = shootCommentCategory(assignment);
        SHOOT_CATEGORY_CACHE.set(assignment, category);
        return category;
    }
    function shootCategoryFamily(assignment) {
        const category = cachedShootCommentCategory(assignment);
        if (category === "BEAUTY" || category === "CONCEPTUAL BEAUTY")
            return "BEAUTY";
        if (category === "PARTNER / COUPLE" || category === "GROUP / ENSEMBLE")
            return "ENSEMBLE";
        return category;
    }
    function shootCategoryRepeatPenalty(assignment, recentAssignments = []) {
        const category = cachedShootCommentCategory(assignment);
        const family = shootCategoryFamily(assignment);
        return recentAssignments.reduce((sum, prior, index) => {
            const isMostRecent = index === recentAssignments.length - 1;
            const priorCategory = cachedShootCommentCategory(prior);
            const priorFamily = shootCategoryFamily(prior);
            if (category === priorCategory)
                return sum + (isMostRecent ? 2.35 : 1.05);
            if (family === priorFamily)
                return sum + (isMostRecent ? 1.65 : .72);
            return sum;
        }, 0);
    }
    function balancedAssignmentOrder(assignments, initialUsage = null, previousAssignments = [], options = {}) {
        const remaining = shuffled(assignments);
        const usage = Object.fromEntries(SKILL_KEYS.map(key => [key, initialUsage?.[key] || 0]));
        const ordered = [];
        const recent = [...previousAssignments].slice(-2);
        const balanceCategories = !!options.balanceCategories;
        while (remaining.length) {
            const scored = remaining.map((assignment, index) => {
                const projected = SKILL_KEYS.map(key => usage[key] + (assignment.weights?.[key] || 0));
                const mean = average(projected);
                const imbalance = average(projected.map(value => (value - mean) ** 2));
                const overlapPenalty = recent.reduce((sum, prior, distance) => sum + assignmentOverlap(assignment, prior) * (distance === recent.length - 1 ? 1.15 : .55), 0);
                const categoryPenalty = balanceCategories ? shootCategoryRepeatPenalty(assignment, recent) : 0;
                const score = imbalance + overlapPenalty * .42 + categoryPenalty + randomBetween(0, .035);
                return { assignment, index, score };
            }).sort((a, b) => a.score - b.score);
            const pick = scored[0];
            const [assignment] = remaining.splice(pick.index, 1);
            ordered.push(assignment);
            recent.push(assignment);
            if (recent.length > 2)
                recent.shift();
            SKILL_KEYS.forEach(key => { usage[key] += assignment.weights?.[key] || 0; });
        }
        return { ordered, usage, recent };
    }
    function takeCategoryBalancedShoot(pool, cursor, recentShoots = []) {
        if (!Array.isArray(pool) || cursor >= pool.length)
            return { shoot: null, cursor };
        const lookAheadEnd = Math.min(pool.length, cursor + 10);
        let bestIndex = cursor;
        let bestScore = Infinity;
        for (let index = cursor; index < lookAheadEnd; index += 1) {
            const candidate = pool[index];
            const categoryPenalty = shootCategoryRepeatPenalty(candidate, recentShoots.slice(-2));
            const overlapPenalty = recentShoots.slice(-2).reduce((sum, prior) => sum + assignmentOverlap(candidate, prior), 0);
            const score = categoryPenalty + overlapPenalty * .22 + randomBetween(0, .02);
            if (score < bestScore) {
                bestScore = score;
                bestIndex = index;
            }
        }
        if (bestIndex !== cursor)
            [pool[cursor], pool[bestIndex]] = [pool[bestIndex], pool[cursor]];
        return { shoot: pool[cursor], cursor: cursor + 1 };
    }
    function createShootPool(country = "none") {
        const normalizedCountry = String(country || "none").trim().toLowerCase();
        const eligibleShoots = SHOOT_LIBRARY.filter(shoot => String(shoot.country || "none").trim().toLowerCase() === normalizedCountry);
        const uniqueByTitle = new Map();
        shuffled(eligibleShoots).forEach(shoot => {
            const key = String(shoot.title || "").trim().toLowerCase();
            if (key && !uniqueByTitle.has(key))
                uniqueByTitle.set(key, shoot);
        });
        return balancedAssignmentOrder([...uniqueByTitle.values()], null, [], { balanceCategories: true }).ordered;
    }
    function isExcludedChallenge(challenge) {
        const searchable = `${challenge?.title || ""} ${challenge?.description || ""} ${challenge?.type || ""}`.toLowerCase();
        return ["final", "finale", "comeback"].some(term => searchable.includes(term));
    }
    function createChallengePool(count, country = "none") {
        const normalizedCountry = String(country || "none").trim().toLowerCase();
        const eligible = CHALLENGE_LIBRARY.filter(challenge => String(challenge.country || "none").trim().toLowerCase() === normalizedCountry
            && !isExcludedChallenge(challenge));
        const uniqueByTitle = new Map();
        shuffled(eligible).forEach(challenge => {
            const key = String(challenge.title || "").trim().toLowerCase();
            if (key && !uniqueByTitle.has(key))
                uniqueByTitle.set(key, challenge);
        });
        if (!uniqueByTitle.size || count <= 0)
            return [];
        return balancedAssignmentOrder([...uniqueByTitle.values()]).ordered.slice(0, count);
    }
