        const match = String(effects || "").match(pattern);
        if (!match)
            return randomBetween(fallbackMin, fallbackMax);
        const firstRaw = match[1];
        if (firstRaw.startsWith("±")) {
            const amount = Number(firstRaw.slice(1)) || Math.max(Math.abs(fallbackMin), Math.abs(fallbackMax));
            return randomBetween(-amount, amount);
        }
        let first = Number(firstRaw);
        let second = match[2] == null ? first : Number(match[2]);
