            return DEFAULT_SKILL;
        const seasonPerformance = clamp(entry?.seasonAverage ?? seasonAverage(profile), 1, 15);
        const currentPerformance = fanVotingCurrentPerformance(entry);
        const fanFavor = fanFavorScale(profile);
        const houseStory = modelHouseCharacterScore(entry.model.id);
        const audienceSkill = fanVotingAudienceSkill(profile);
        const archetypeAppeal = modelArchetypeCharacterPotential(entry.model);
        const charisma = clamp(profile.traits.charisma, 1, 15);
        const publicSwing = randomBetween(1, 15);
