            entry.shoot = shootScore;
            profile.history.shoots.push(shootScore);
            addFatigue(profile, 8);
            const hasChallenge = Number.isFinite(entry.challenge);
            const challengeForPerformance = Number.isFinite(entry.challengePerformance) ? entry.challengePerformance : entry.challenge;
            const weekly = hasChallenge ? shootScore * .70 + challengeForPerformance * .30 : shootScore;
            profile.history.totals.push(weekly);
            entry.potential = profile.traits.potential;
            entry.judgeFavor = profile.perception.judges;
