        const [returnee] = reordered.splice(currentIndex, 1);
        const maxInsert = Math.min(lastTopHalfIndex, reordered.length);
        const minInsert = maxInsert >= 1 ? 1 : 0;
        const insertAt = minInsert + Math.floor(Math.random() * (maxInsert - minInsert + 1));
        reordered.splice(insertAt, 0, returnee);
        return reordered;
