            score: Math.round(portfolio * 100) / 100,
            averageShoot: Math.round(averageShoot * 100) / 100,
            challengeAverage: Math.round(challengeAverage * 100) / 100,
            consistency: Math.round(consistency * 100) / 100,
            trajectory: Math.round(trajectory * 100) / 100,
            versatility: Math.round(versatility * 100) / 100,
            strongestCategory: sortedCategories[0]?.category || "None",
