        const difficulty = assignment.difficulty ?? 5;
        const adaptability = ((profile.traits.adaptability - DEFAULT_TRAIT) / 7) * (unfamiliarity / 10) * .58;
        const composure = ((profile.traits.confidence - DEFAULT_TRAIT) / 7) * .22;
        const professional = kind === "challenge" ? ((profile.traits.professionalism - DEFAULT_TRAIT) / 7) * .18 : 0;
        const currentConfidence = (profile.state.confidence / 20) * .24;
        const stressPenalty = (profile.state.stress / 100) * .58;
