            const challengeWinner = isMakeoverEpisode
                ? null
                : entries.reduce((best, entry) => !best || entry.challenge > best.challenge ? entry : best, null);
            const houseAfter = makeHouseEvents(competingProfiles, "after", { challenge: challenge || shoot, shoot, challengeWinner: challengeWinner ? profileById(challengeWinner.model.id) : null });
            completeShootEntries(entries, shoot);
