        const initials = (label.match(/[A-Za-z0-9]/g) || ["M"]).slice(0, 2).join("").toUpperCase();
        const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 150">
      <rect width="120" height="150" fill="#1c1c20"/>
      <circle cx="60" cy="55" r="27" fill="#34343a"/>
      <path d="M20 138c5-31 19-47 40-47s35 16 40 47" fill="#34343a"/>
      <text x="60" y="145" text-anchor="middle" fill="#8f8f98" font-family="Arial,sans-serif" font-size="12" font-weight="700">${initials}</text>
    </svg>`;
        return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
