    document.addEventListener("click", event => {
        const go = event.target.closest("[data-go]");
        if (go)
            showScreen(go.dataset.go);
        const panel = event.target.closest("[data-panel-target], [data-open-panel]");
        if (panel)
            openEpisodePanel(panel.dataset.panelTarget || panel.dataset.openPanel);
        const finalePanel = event.target.closest("[data-finale-panel], [data-finale-open]");
        if (finalePanel)
            openFinalePanel(finalePanel.dataset.finalePanel || finalePanel.dataset.finaleOpen);
        const finaleAction = event.target.closest("[data-finale-action]");
        if (finaleAction && state.finaleEpisode) {
            if (finaleAction.dataset.finaleAction === "reveal-fan-favorite")
                animateFanFavoriteReveal();
            if (finaleAction.dataset.finaleAction === "reveal-winner")
                animateFinaleWinnerReveal();
        }
        const votingComebackAction = event.target.closest("[data-voting-comeback-action]");
        if (votingComebackAction?.dataset.votingComebackAction === "reveal")
            animateVotingComebackReveal();
        const fanComebackAction = event.target.closest("[data-fan-comeback-action]");
        if (fanComebackAction?.dataset.fanComebackAction === "reveal")
            animateFanComebackReveal();
        const stats = event.target.closest("[data-stats-target]");
        if (stats)
            openStatsPanel(stats.dataset.statsTarget);
        const castingPanel = event.target.closest("[data-casting-panel]");
        if (castingPanel)
            openCastingPanel(castingPanel.dataset.castingPanel);
        const castingAction = event.target.closest("[data-casting-action]");
        if (castingAction) {
            const action = castingAction.dataset.castingAction;
            if (action === "round-one-reveal")
                runCastingReveal("round-one");
            if (action === "final-cast-reveal")
                runCastingReveal("final-cast");
            if (action === "begin-competition") {
                clearTimeout(state.castingTimer);
                state.castingTimer = null;
                state.viewingCasting = false;
                state.viewingFinale = false;
                state.currentEpisodeIndex = 0;
                populateEpisodeDropdown();
                renderCurrentEpisode(true);
                queuePersist();
            }
        }
        const averageSort = event.target.closest("[data-average-sort]");
        if (averageSort) {
            const key = averageSort.dataset.averageSort;
            if (["rank", "place", "model", "total", "count", "average"].includes(key)) {
                if (state.averageCalloutSort.key === key) {
                    state.averageCalloutSort.direction = state.averageCalloutSort.direction === "asc" ? "desc" : "asc";
                }
                else {
                    state.averageCalloutSort = { key, direction: key === "place" || key === "rank" || key === "average" || key === "model" ? "asc" : "desc" };
                }
                updateAverageCalloutOrder();
                queuePersist();
            }
        }
        const remove = event.target.closest("[data-remove-model]");
        if (remove) {
            state.evenGenderSelection = false;
            state.selectedIds.delete(remove.dataset.removeModel);
            clearSeasonSimulation();
            renderCastBuilder();
        }
        const edit = event.target.closest("[data-edit-model]");
        if (edit) {
            const model = modelById(edit.dataset.editModel);
            if (model?.isCustom)
                openCustomContestantDialog(model);
            else
                openModelEditor(edit.dataset.editModel);
        }
        if (event.target.closest("[data-close-dialog]"))
            event.target.closest("dialog")?.close();
    });
    document.addEventListener("change", event => {
        if (event.target.matches("[data-filter-all-shows]")) {
            if (event.target.checked || state.selectedShows.size === 0) {
                state.selectedShows.clear();
                state.selectedSeasons.clear();
            }
            renderDirectory();
            return;
        }
        if (event.target.matches("[data-filter-show]")) {
            const value = event.target.value;
            if (event.target.checked)
                state.selectedShows.add(value);
            else
                state.selectedShows.delete(value);
            state.selectedSeasons.clear();
            renderDirectory();
        }
        if (event.target.matches("[data-filter-season]")) {
            const value = event.target.value;
            if (event.target.checked)
                state.selectedSeasons.add(value);
            else
                state.selectedSeasons.delete(value);
            renderDirectory();
        }
    });
